<script>const scope=document.getElementById('scope'),checks=[...document.querySelectorAll('.product-check')],heading=document.getElementById('product-heading'),help=document.getElementById('product-help');function mode(){const full=scope.value==='full';heading.textContent=full?'Full catalogue':'Specific products';help.textContent=full?'All active products are selected. Uncheck anything that should be excluded.':'Search and check every product the user must count.';checks.forEach(c=>c.checked=full)}scope.addEventListener('change',mode);mode();document.getElementById('product-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-product]').forEach(row=>row.hidden=!row.dataset.product.includes(q))});</script>
